"""data.py: the handbook, the questions and the stand-in assistant's answers for Lab 5 (you do not edit this file).

Everything is invented. The corpus is a small "leisure services handbook" for a fictional council: one
document per venue, each a few sentences such as "Marlow Pool has capacity for 120 visitors." A stand-in
assistant (make_answers) answers one question per call. It does what real assistants do in the ways chapters 11
and 12 describe, chosen by a seeded draw, and every answer carries the gold labels the generator knows:

    good            states the fact, cites the right document with a real quotation
    wrong_number    cites the right sentence but changes the figure
    unsupported     the venue's document does not say it; the assistant invents a figure anyway (an
                    unanswerable question answered) and cites a real but irrelevant sentence
    near_miss       a qualifier is changed ("child" for "adult", "weekends" for "weekdays"); every word
                    of the claim looks supported, but the claim is not
    misattributed   a true statement attached to the wrong venue's document (a real quotation, wrong place)
    fake_quote      the right document, but the "quotation" is a paraphrase that is not in the text
    fabricated      a citation to a document that does not exist

An answer is `correct` only if every statement is true AND properly attributed (real source, real quotation,
cited text supports the statement). `self_conf` is the stand-in's own confidence in the answer: noisy, and
inflated, like the models of chapter 11.

make_dataset(seed, n) is deterministic: the same seed always gives the same answers.
"""
import random

# ----------------------------------------------------------------------------- the handbook

VENUES = ["Marlow Pool", "Eastgate Library", "Riverside Gym", "Kelham Archive", "Harbour Museum",
          "Pinecroft Skate Park", "Orchard Theatre", "Westbury Tennis Courts", "Stonebridge Sports Hall",
          "Linden Reading Room", "St Anne’s Hall", "Cobalt Climbing Wall", "Fenwick Botanic Garden",
          "Quayside Ice Rink"]

# attribute -> (document sentence, question, value generator, ways to say it, near-miss rewrite)
ATTRS = {
    "capacity": dict(
        sentence="{V} has capacity for {n} visitors.",
        question="How many visitors can {V} hold?",
        values=lambda r: r.randrange(40, 400, 10),
        phrasings=["{V} has capacity for {n} visitors.", "{V} can hold {n} visitors.",
                   "The capacity of {V} is {n} visitors.", "{V} has room for {n} visitors at a time."],
        near="{V} has capacity for {n} staff.",
        more="{V} can hold more than {m} visitors."),
    "fee": dict(
        sentence="Adult entry to {V} costs {n} pounds.",
        question="How much does adult entry to {V} cost?",
        values=lambda r: r.randrange(2, 16),
        phrasings=["Adult entry to {V} costs {n} pounds.", "An adult ticket for {V} is {n} pounds.",
                   "{V} charges adults {n} pounds to enter.", "Adults pay {n} pounds for entry to {V}."],
        near="Child entry to {V} costs {n} pounds.",
        more="Adult entry to {V} costs less than {m} pounds."),
    "opened": dict(
        sentence="{V} opened in {n}.",
        question="When did {V} open?",
        values=lambda r: r.randrange(1950, 2021),
        phrasings=["{V} opened in {n}.", "{V} first opened its doors in {n}.", "The opening year of {V} was {n}."],
        near="{V} was renovated in {n}.",
        more="{V} opened before {m}."),
    "closing": dict(
        sentence="{V} closes at {n} pm on weekdays.",
        question="What time does {V} close on weekdays?",
        values=lambda r: r.randrange(5, 11),
        phrasings=["{V} closes at {n} pm on weekdays.", "On weekdays {V} closes at {n} pm.",
                   "Closing time at {V} is {n} pm on weekdays."],
        near="{V} closes at {n} pm on weekends.",
        more="{V} closes after {m} pm on weekdays."),
    "advance": dict(
        sentence="Group bookings at {V} must be made {n} days in advance.",
        question="How far ahead must a group book {V}?",
        values=lambda r: r.randrange(1, 15),
        phrasings=["Group bookings at {V} must be made {n} days in advance.",
                   "A group must book {V} {n} days in advance.", "{V} needs group bookings {n} days in advance."],
        near="Individual bookings at {V} must be made {n} days in advance.",
        more="Group bookings at {V} need more than {m} days notice."),
    "parking": dict(
        sentence="{V} has {n} car parking spaces.",
        question="How many car parking spaces does {V} have?",
        values=lambda r: r.randrange(10, 200, 5),
        phrasings=["{V} has {n} car parking spaces.", "There are {n} car parking spaces at {V}.",
                   "{V} offers {n} spaces for car parking."],
        near="{V} has {n} bicycle parking spaces.",
        more="{V} has at least {m} car parking spaces."),
}
ATTR_NAMES = list(ATTRS)


def _build_corpus():
    rng = random.Random(2024)
    corpus, facts = {}, {}
    for i, venue in enumerate(VENUES, 1):
        attrs = rng.sample(ATTR_NAMES, 4)               # each venue's document states 4 of the 6 attributes
        facts[venue] = {}
        sentences = []
        for a in ATTR_NAMES:
            if a in attrs:
                n = ATTRS[a]["values"](rng)
                facts[venue][a] = n
                sentences.append(ATTRS[a]["sentence"].format(V=venue, n=n))
        corpus["D%02d" % i] = " ".join(sentences)
    return corpus, facts


CORPUS, FACTS = _build_corpus()
DOC_OF = {venue: "D%02d" % i for i, venue in enumerate(VENUES, 1)}
KINDS = [("good", 0.56), ("wrong_number", 0.10), ("unsupported", 0.09), ("near_miss", 0.06),
         ("misattributed", 0.07), ("fake_quote", 0.06), ("fabricated", 0.06)]


# ----------------------------------------------------------------------------- one answer

def _sentence(venue, attr):
    return ATTRS[attr]["sentence"].format(V=venue, n=FACTS[venue][attr])


def _quote(rng, sentence):
    """A real quotation from the sentence: the whole thing, or a tail, sometimes with messy case or spacing."""
    words = sentence.split(" ")
    q = sentence
    r = rng.random()
    if r < 0.30 and len(words) > 5:
        q = " ".join(words[len(words) // 2 - 1:])
    elif r < 0.45 and len(words) > 6:
        cut = len(words) // 2
        q = " ".join(words[:2]) + " ... " + " ".join(words[cut + 1:])
    r = rng.random()
    if r < 0.15:
        q = q.lower()
    elif r < 0.25:
        q = q.replace(" ", "  ", 1)
    elif r < 0.32:
        q = q.replace("’", "'")
    return q.rstrip(".") + ("." if rng.random() < 0.5 else "")


def _pick_kind(rng):
    u, acc = rng.random(), 0.0
    for kind, p in KINDS:
        acc += p
        if u < acc:
            return kind
    return KINDS[0][0]


def _statement_good(rng, venue, attr):
    ph = rng.choice(ATTRS[attr]["phrasings"]) if rng.random() < 0.7 else ATTRS[attr]["sentence"]
    text = ph.format(V=venue, n=FACTS[venue][attr])
    if rng.random() < 0.07:                           # a true but quantified claim: the rule-based judge cannot do this
        n = FACTS[venue][attr]
        bound = {"capacity": n - 20, "parking": n - 5, "fee": n + 3, "opened": n + 5, "closing": n - 1, "advance": n - 1}[attr]
        text = ATTRS[attr]["more"].format(V=venue, m=max(1, bound))
    return dict(text=text, cites=[dict(doc=DOC_OF[venue], quote=_quote(rng, _sentence(venue, attr)))],
                gold="SUPPORTED", cite_status=["ok"])


def make_answer(rng, idx):
    """One generated answer. Returns a dict (see the module docstring)."""
    kind = _pick_kind(rng)
    venue = rng.choice(VENUES)
    have = list(FACTS[venue])
    missing = [a for a in ATTR_NAMES if a not in have]
    if kind == "unsupported":
        attr = rng.choice(missing)
    else:
        attr = rng.choice(have)
    q = ATTRS[attr]["question"].format(V=venue)
    answerable = attr in have
    stmts = []
    if kind == "good":
        stmts.append(_statement_good(rng, venue, attr))
    elif kind == "wrong_number":
        true = FACTS[venue][attr]
        wrong = true
        while wrong == true:
            wrong = ATTRS[attr]["values"](rng)
        text = rng.choice(ATTRS[attr]["phrasings"]).format(V=venue, n=wrong)
        stmts.append(dict(text=text, cites=[dict(doc=DOC_OF[venue], quote=_quote(rng, _sentence(venue, attr)))],
                          gold="CONTRADICTED", cite_status=["ok"]))
    elif kind == "unsupported":
        n = ATTRS[attr]["values"](rng)
        text = rng.choice(ATTRS[attr]["phrasings"]).format(V=venue, n=n)
        other = rng.choice(have)                      # cites a real sentence about a different attribute
        stmts.append(dict(text=text, cites=[dict(doc=DOC_OF[venue], quote=_quote(rng, _sentence(venue, other)))],
                          gold="NOT_ENOUGH_INFO", cite_status=["ok"]))
    elif kind == "near_miss":
        n = FACTS[venue][attr]
        text = ATTRS[attr]["near"].format(V=venue, n=n)
        stmts.append(dict(text=text, cites=[dict(doc=DOC_OF[venue], quote=_quote(rng, _sentence(venue, attr)))],
                          gold="NOT_ENOUGH_INFO", cite_status=["ok"]))
    elif kind == "misattributed":
        text = rng.choice(ATTRS[attr]["phrasings"]).format(V=venue, n=FACTS[venue][attr])
        others = [v for v in VENUES if v != venue and attr in FACTS[v]]
        wrong_v = rng.choice(others)
        stmts.append(dict(text=text, cites=[dict(doc=DOC_OF[wrong_v], quote=_quote(rng, _sentence(wrong_v, attr)))],
                          gold="NOT_ENOUGH_INFO", cite_status=["ok"]))
    elif kind == "fake_quote":
        text = rng.choice(ATTRS[attr]["phrasings"]).format(V=venue, n=FACTS[venue][attr])
        fake = "the official handbook confirms that " + text[0].lower() + text[1:]
        stmts.append(dict(text=text, cites=[dict(doc=DOC_OF[venue], quote=fake)],
                          gold="SUPPORTED", cite_status=["quote_not_found"]))
    else:                                              # fabricated
        n = ATTRS[attr]["values"](rng)
        text = rng.choice(ATTRS[attr]["phrasings"]).format(V=venue, n=n)
        doc = rng.choice(["D%02d" % rng.randrange(40, 90), "handbook-2023", "H%d" % rng.randrange(100, 999)])
        stmts.append(dict(text=text, cites=[dict(doc=doc, quote=_quote(rng, _sentence(venue, attr)))],
                          gold="NOT_ENOUGH_INFO", cite_status=["no_such_source"]))
    # a second, correct statement in about a third of the answers (a different attribute of the same venue)
    if rng.random() < 0.35 and len(have) > 1:
        a2 = rng.choice([a for a in have if a != attr])
        extra = _statement_good(rng, venue, a2)
        if rng.random() < 0.5:
            stmts.append(extra)
        else:
            stmts.insert(0, extra)
    # the 'good' extra statement may be a quantified claim; gold stays SUPPORTED (it is true)
    correct = kind == "good"
    base = 0.83 if kind == "good" else (0.68 if kind == "unsupported" else 0.62)
    conf = min(0.99, max(0.05, rng.gauss(base, 0.10 if kind == "good" else 0.16)))
    return dict(id="A%04d" % idx, question=q, answerable=answerable, kind=kind, statements=stmts,
                correct=correct, self_conf=round(conf, 3), venue=venue)


def make_dataset(seed, n):
    """n generated answers, deterministic in the seed."""
    rng = random.Random(seed)
    return [make_answer(rng, i) for i in range(n)]


# the three standard sets
def dev_set():
    """120 answers for building and debugging (milestones 1 to 3)."""
    return make_dataset(5, 120)


def calibration_set():
    """600 answers on which thresholds are chosen (milestone 5)."""
    return make_dataset(11, 600)


def test_set():
    """600 answers, never used for choosing anything (milestones 4 and 5)."""
    return make_dataset(12, 600)
